package com.coraline.bobinsky;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.Level;
import net.minecraftforge.event.level.*;
import net.minecraftforge.event.entity.player.*;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.eventbus.api.*;
import net.minecraftforge.fml.common.Mod;
import net.minecraft.nbt.CompoundTag;
@Mod.EventBusSubscriber(modid="coraline")
public final class BobinskyHouseProtection {
    public static java.util.List<CompoundTag> houses(Level level){if(level.isClientSide||!level.dimension().equals(Level.OVERWORLD)||level.getServer()==null)return java.util.List.of();var d=BobinskyVisitData.get(level.getServer());var all=new java.util.ArrayList<CompoundTag>(d.visits.values());all.addAll(d.teaVisits.values());for(var visit:d.teaVisits.values())if(visit.contains("PreviousTeaVisit"))all.add(visit.getCompound("PreviousTeaVisit"));return all;}
    public static CompoundTag house(Level level,BlockPos pos){for(var v:houses(level))if(v.getBoolean("Active")&&v.contains("Originals")&&BobinskyHouse.bounds(v).contains(net.minecraft.world.phys.Vec3.atCenterOf(pos)))return v;return null;}
    @SubscribeEvent(priority=EventPriority.HIGHEST) public static void breakBlock(BlockEvent.BreakEvent e){if(e.getLevel() instanceof Level level&&(house(level,e.getPos())!=null||level.getBlockState(e.getPos()).is(com.coraline.registry.ModBlocks.CHEESE_PARCEL.get())))e.setCanceled(true);}
    @SubscribeEvent(priority=EventPriority.HIGHEST) public static void place(BlockEvent.EntityPlaceEvent e){if(!(e.getLevel() instanceof Level level)||level.isClientSide||!level.dimension().equals(Level.OVERWORLD))return;if(house(level,e.getPos())!=null){e.setCanceled(true);return;}if(e.getEntity() instanceof net.minecraft.world.entity.player.Player){var data=BobinskyVisitData.get(level.getServer());data.playerPlaced.add(e.getPos().asLong());data.setDirty();if(e instanceof BlockEvent.EntityMultiPlaceEvent multi)for(var snapshot:multi.getReplacedBlockSnapshots())data.playerPlaced.add(snapshot.getPos().asLong());}}
    @SubscribeEvent(priority=EventPriority.HIGHEST) public static void click(PlayerInteractEvent.RightClickBlock e){if(e.getLevel().isClientSide)return;var v=house(e.getLevel(),e.getPos());if(v==null)return;if(com.coraline.feast.MissingParentsTea.isVisit(v)){e.setCanceled(true);e.setCancellationResult(net.minecraft.world.InteractionResult.SUCCESS);if(e.getHand()==net.minecraft.world.InteractionHand.MAIN_HAND&&e.getEntity() instanceof ServerPlayer p)com.coraline.feast.MissingParentsTea.block(p,v,e.getPos());return;}if(v.getBoolean("Tea")&&v.getInt("Phase")==com.coraline.tea.TeaVisit.DRINK&&e.getEntity().getItemInHand(e.getHand()).is(com.coraline.registry.ModItems.JASMINE_TEA.get())){e.setUseBlock(net.minecraftforge.eventbus.api.Event.Result.DENY);e.setUseItem(net.minecraftforge.eventbus.api.Event.Result.ALLOW);return;}e.setCanceled(true);e.setCancellationResult(net.minecraft.world.InteractionResult.SUCCESS);if(e.getEntity() instanceof ServerPlayer p&&BobinskyHouse.isDoor(v,e.getPos())){if(v.getBoolean("Tea"))com.coraline.tea.TeaVisit.knock(p,v);else BobinskyVisit.knock(p,v);}}
    @SubscribeEvent(priority=EventPriority.HIGHEST) public static void left(PlayerInteractEvent.LeftClickBlock e){if(e.getLevel().isClientSide)return;var v=house(e.getLevel(),e.getPos());if(v==null)return;e.setCanceled(true);if(com.coraline.feast.MissingParentsTea.isVisit(v))return;if(e.getEntity() instanceof ServerPlayer p&&BobinskyHouse.isDoor(v,e.getPos())){if(v.getBoolean("Tea"))com.coraline.tea.TeaVisit.knock(p,v);else BobinskyVisit.knock(p,v);}}
    @SubscribeEvent public static void explosion(ExplosionEvent.Detonate e){e.getAffectedBlocks().removeIf(pos->house(e.getLevel(),pos)!=null||e.getLevel().getBlockState(pos).is(com.coraline.registry.ModBlocks.CHEESE_PARCEL.get()));}
    @SubscribeEvent(priority=EventPriority.HIGHEST) public static void fluid(BlockEvent.FluidPlaceBlockEvent e){if(e.getLevel() instanceof Level level&&house(level,e.getPos())!=null)e.setCanceled(true);}
    @SubscribeEvent(priority=EventPriority.HIGHEST) public static void piston(PistonEvent.Pre e){if(e.getLevel() instanceof Level level)for(int i=0;i<14;i++)if(house(level,e.getPos().relative(e.getDirection(),i))!=null||level.getBlockState(e.getPos().relative(e.getDirection(),i)).is(com.coraline.registry.ModBlocks.CHEESE_PARCEL.get())){e.setCanceled(true);return;}}
    @SubscribeEvent(priority=EventPriority.HIGHEST) public static void pickup(EntityItemPickupEvent e){var stack=e.getItem().getItem();var tag=stack.getTag();if(tag!=null&&tag.hasUUID("BobinskyOwner")&&!e.getEntity().getUUID().equals(tag.getUUID("BobinskyOwner")))e.setCanceled(true);}
    @SubscribeEvent public static void loaded(net.minecraftforge.event.entity.EntityJoinLevelEvent e){if(e.getLevel().isClientSide||!(e.getEntity() instanceof net.minecraft.world.entity.item.ItemEntity item))return;var data=BobinskyVisitData.get(e.getLevel().getServer());var tag=item.getPersistentData();CompoundTag v=null;java.util.UUID token=null;
        if(tag.hasUUID("SceneOwner")&&tag.hasUUID("SceneToken")){v=(tag.getBoolean("TeaProp")?data.teaVisits:data.visits).get(tag.getUUID("SceneOwner"));token=tag.getUUID("SceneToken");}
        else if(item.getItem().hasTag()){var t=item.getItem().getTag();if(t.hasUUID("BobinskyOwner")&&t.hasUUID("BobinskyToken")){v=data.visits.get(t.getUUID("BobinskyOwner"));token=t.getUUID("BobinskyToken");}else if(t.hasUUID("TeaOwner")&&t.hasUUID("TeaToken")){v=data.teaVisits.get(t.getUUID("TeaOwner"));token=t.getUUID("TeaToken");}}
        if(token!=null&&(v==null||!v.getBoolean("Active")||v.getBoolean("Cancelled")||!v.getUUID("Token").equals(token)))e.setCanceled(true);
    }
    @SubscribeEvent public static void player(TickEvent.PlayerTickEvent e){if(e.phase!=TickEvent.Phase.END||!(e.player instanceof ServerPlayer p)||!p.level().dimension().equals(Level.OVERWORLD))return;for(var v:houses(p.level()))if(v.getBoolean("Active")&&v.contains("Originals")&&BobinskyHouse.insideRooms(v,p.position())&&(!com.coraline.tea.TeaVisit.canEnter(v)||!v.getUUID("Owner").equals(p.getUUID()))){var at=BobinskyHouse.front(v).north();p.teleportTo(at.getX()+.5,at.getY(),at.getZ()+.5);}}
}
